std::list<CGALTriangle> triangles;
CGAL::AABB_tree<AABB_triangle_traits> tree;
Point3d p;
CGALPoint query_point(p.x(), p.y(), p.z());
CGAL::Point_3<CGAL::Simple_cartesian<double>> nearest_point;
std::list<CGAL::Point_3<CGAL::Simple_cartesian<double>>> nearest_points;
tree.closest_point(query_point, nearest_point, nearest_points);
return Point3d(nearest_point.x(), nearest_point.y(), nearest_point.z());

